sys_ui_action.script:
var summary = "VOLLMACHT / POWER OF ATTORNEY (§81a AufenthG)\n" +
    "============================================\n\n" +
    "Candidate: " + current.u_candidate_name + "\n" +
    "Nationality: " + current.u_nationality + "\n" +
    "Passport: " + current.u_passport_number + "\n" +
    "Jurisdiction: " + current.u_target_city + "\n" +
    "Category: " + current.u_visa_category.getDisplayValue() + "\n" +
    "Statutory Fee: €" + current.u_fee_amount + " (Status: " + current.u_fee_status + ")\n\n" +
    "Generated by: " + gs.getUserDisplayName() + "\n" +
    "Date: " + new GlideDateTime().getDisplayValue();

current.work_notes = summary;
current.u_poa_signed = true;
current.update();

gs.addInfoMessage("Vollmacht and legal summary generated and logged in Activity Stream.");
action.setRedirectURL(current);
